package com.example.onlineshop.catalog.api;
import com.example.onlineshop.catalog.application.CatalogService;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.example.onlineshop.catalog.application.CatalogProductRepository; import com.example.onlineshop.catalog.domain.*; import com.fasterxml.jackson.databind.*; import java.nio.file.*; import java.time.Instant; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.springframework.test.web.servlet.MockMvc; import org.testcontainers.junit.jupiter.Container; import org.testcontainers.junit.jupiter.Testcontainers; import org.testcontainers.postgresql.PostgreSQLContainer;
@Tag("docker") @Testcontainers(disabledWithoutDocker=false) @SpringBootTest @AutoConfigureMockMvc class CatalogApiTest {
 @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:16.6-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc; @Autowired CatalogProductRepository repository; @Autowired CatalogService catalog;
 @BeforeEach void reset(){jdbc.execute("TRUNCATE product_attribute,category,product,products CASCADE");jdbc.execute("CALL catalog_preflight_and_backfill_legacy_products(500)");}
 @Test void createListDetailAndProblems() throws Exception {var body="{\"name\":\"Synthetic Tea\",\"description\":\"Fixture\",\"price\":\"12.30\",\"currency\":\"NZD\",\"stockQuantity\":4}";var json=mvc.perform(post("/api/v1/products").contentType("application/json").content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.price").value("12.30")).andReturn().getResponse().getContentAsString();var id=json.replaceAll(".*\\\"id\\\":\\\"([^\\\"]+).*","$1");mvc.perform(get("/api/v1/products/"+id)).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(id));mvc.perform(get("/api/v1/products")).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1));Assertions.assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM products",Integer.class));Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_sku WHERE product_id=? AND is_default",Integer.class,UUID.fromString(id)));var actor=UUID.randomUUID();var now=Instant.parse("2026-10-24T00:00:00Z");var attribute=new ProductAttribute(UUID.randomUUID(),"origin","Origin",AttributeDataType.TEXT,AttributeScope.PRODUCT,false,LifecycleStatus.ACTIVE);attribute.addValue(UUID.randomUUID(),"nz","New Zealand");repository.save(attribute,actor,now);repository.save(new Category(UUID.randomUUID(),"tea","Tea",null,LifecycleStatus.ACTIVE,0,0),actor,now);repository.save(new ProductImage(UUID.randomUUID(),UUID.fromString(id),null,"/tea.png","Tea",0,true,0),actor,now);Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_attribute_value",Integer.class));Assertions.assertEquals(actor,jdbc.queryForObject("SELECT created_by FROM category",UUID.class));Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_image",Integer.class));mvc.perform(post("/api/v1/products").contentType("application/json").content("{}" )).andExpect(status().isUnprocessableEntity()).andExpect(content().contentType("application/problem+json"));mvc.perform(get("/api/v1/products/00000000-0000-0000-0000-000000000000")).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("PRODUCT_NOT_FOUND"));}
 @Test void malformedIs400() throws Exception {mvc.perform(post("/api/v1/products").contentType("application/json").content("{" )).andExpect(status().isBadRequest());}
 @Test void frameworkErrorsUseProblemDetails() throws Exception {mvc.perform(put("/api/v1/products").contentType("application/json").content("{}" )).andExpect(status().isMethodNotAllowed()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("METHOD_NOT_ALLOWED"));mvc.perform(post("/api/v1/products").contentType("application/xml").content("<product/>" )).andExpect(status().isUnsupportedMediaType()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("UNSUPPORTED_MEDIA_TYPE"));mvc.perform(get("/api/v1/products/x/y")).andExpect(status().isNotFound()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("RESOURCE_NOT_FOUND"));}
 @Test void publishesApprovedOpenApiResponses() throws Exception {mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['201']").exists()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['400'].content['application/problem+json']").exists()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['422'].content['application/problem+json']").exists()).andExpect(jsonPath("$.paths['/api/v1/products/{productId}'].get.responses['404'].content['application/problem+json']").exists());}
 @Test void checkedOpenApiPathsAndResponsesMatchRuntime() throws Exception {var mapper=new ObjectMapper();JsonNode runtime=mapper.readTree(mvc.perform(get("/v3/api-docs")).andReturn().getResponse().getContentAsString());JsonNode checked=mapper.readTree(Paths.get("../../tests/contracts/catalog-api.json").toFile());Assertions.assertEquals(fieldNames(checked.path("paths")),fieldNames(runtime.path("paths")));Assertions.assertEquals(fieldNames(checked.path("components").path("schemas")),fieldNames(runtime.path("components").path("schemas")));for(String path:fieldNames(checked.path("paths"))){for(String method:fieldNames(checked.path("paths").path(path))){Assertions.assertEquals(fieldNames(checked.path("paths").path(path).path(method).path("responses")),fieldNames(runtime.path("paths").path(path).path(method).path("responses")),path+" "+method);}}}
 @Test void persistsAssignmentsCategoriesAndVersionedArchive() {var now=Instant.now().minusSeconds(60);var actor=UUID.randomUUID();var attribute=new ProductAttribute(UUID.randomUUID(),"colour","Colour",AttributeDataType.TEXT,AttributeScope.BOTH,true,true,true,"{}",4,LifecycleStatus.ACTIVE);var red=attribute.addValue(UUID.randomUUID(),"red","Red");repository.save(attribute,actor,now);var category=new Category(UUID.randomUUID(),"tea","Tea","Tea products",null,LifecycleStatus.ACTIVE,2,0);repository.save(category,actor,now);var product=new CatalogProduct(UUID.randomUUID(),null,"assigned-tea","Assigned Tea","Fixture",LifecycleStatus.ACTIVE,actor,actor,now,now,0);var sku=new ProductSku(UUID.randomUUID(),"ASSIGNED-TEA",LifecycleStatus.ACTIVE,new java.math.BigDecimal("12.30"),"NZD",4,true,0);sku.assign(attribute,red);product.addSku(sku);product.assign(attribute,red);product.addCategory(category.id());repository.save(product);Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_attribute_assignment WHERE product_id=?",Integer.class,product.id()));Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_sku_attribute_value WHERE product_sku_id=?",Integer.class,sku.id()));Assertions.assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM product_category WHERE product_id=?",Integer.class,product.id()));catalog.archive(product.id(),actor,0);Assertions.assertEquals("ARCHIVED",jdbc.queryForObject("SELECT status FROM product WHERE id=?",String.class,product.id()));Assertions.assertEquals("ARCHIVED",jdbc.queryForObject("SELECT status FROM product_sku WHERE id=?",String.class,sku.id()));Assertions.assertThrows(OptimisticConflictException.class,()->{product.deactivate(actor,now.plusSeconds(2),0);repository.save(product);});}
 @Test void persistsTwoAxisVariantAndAdvancesAggregateVersionForChildOnlyMutation(){var now=Instant.now().minusSeconds(60);var actor=UUID.randomUUID();var colour=new ProductAttribute(UUID.randomUUID(),"axis-colour","Colour",AttributeDataType.TEXT,AttributeScope.SKU,true,LifecycleStatus.ACTIVE);var red=colour.addValue(UUID.randomUUID(),"red","Red");var size=new ProductAttribute(UUID.randomUUID(),"axis-size","Size",AttributeDataType.TEXT,AttributeScope.SKU,true,LifecycleStatus.ACTIVE);var large=size.addValue(UUID.randomUUID(),"large","Large");repository.save(colour,actor,now);repository.save(size,actor,now);var product=new CatalogProduct(UUID.randomUUID(),null,"two-axis","Two Axis","Fixture",LifecycleStatus.ACTIVE,actor,actor,now,now,0);var sku=new ProductSku(UUID.randomUUID(),"TWO-AXIS",LifecycleStatus.ACTIVE,new java.math.BigDecimal("12.30"),"NZD",4,true,0);sku.assign(colour,red);sku.assign(size,large);product.addSku(sku);repository.save(product);Assertions.assertEquals(147,jdbc.queryForObject("SELECT length(variant_signature) FROM product_sku WHERE id=?",Integer.class,sku.id()));var firstWriter=repository.findAggregate(product.id()).orElseThrow();var staleWriter=repository.findAggregate(product.id()).orElseThrow();firstWriter.defaultSku().changeStock(5,0);var saved=repository.save(firstWriter);Assertions.assertEquals(1,saved.version());Assertions.assertEquals(5,jdbc.queryForObject("SELECT available_quantity FROM product_sku WHERE id=?",Integer.class,sku.id()));staleWriter.deactivate(actor,now.plusSeconds(1),0);Assertions.assertThrows(OptimisticConflictException.class,()->repository.save(staleWriter));Assertions.assertEquals(1,jdbc.queryForObject("SELECT version FROM product WHERE id=?",Long.class,product.id()));}
 @Test void transactionRollsBackAndListTotalMatchesRepresentableRows() throws Exception {var now=Instant.parse("2026-10-24T00:00:00Z");var id=UUID.randomUUID();jdbc.update("INSERT INTO product(id,slug,name,description,status,created_at,updated_at,version) VALUES (?,?,?,?,?,?,?,0)",id,"orphan","Orphan","", "ACTIVE",java.sql.Timestamp.from(now),java.sql.Timestamp.from(now));var body="{\"name\":\"Visible Tea\",\"description\":\"Fixture\",\"price\":\"1.00\",\"currency\":\"NZD\",\"stockQuantity\":1}";mvc.perform(post("/api/v1/products").contentType("application/json").content(body)).andExpect(status().isCreated());mvc.perform(get("/api/v1/products")).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1)).andExpect(jsonPath("$.content.length()").value(1));String collision=jdbc.queryForObject("SELECT sku FROM product_sku LIMIT 1",String.class);var failed=new CatalogProduct(UUID.randomUUID(),null,"rollback","Rollback","",LifecycleStatus.ACTIVE,null,null,now,now,0);failed.addSku(new ProductSku(UUID.randomUUID(),collision,LifecycleStatus.ACTIVE,new java.math.BigDecimal("1.00"),"NZD",1,true,0));Assertions.assertThrows(RuntimeException.class,()->repository.save(failed));Assertions.assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM product WHERE id=?",Integer.class,failed.id()));}
 @Test void v1GoldenShapeAndNameSemanticsRemainFrozen() throws Exception {var response=mvc.perform(post("/api/v1/products").contentType("application/json").content("{\"name\":\"  Padded Tea  \",\"description\":\"Fixture\",\"price\":\"2.00\",\"currency\":\"NZD\",\"stockQuantity\":2}")).andExpect(status().isCreated()).andExpect(jsonPath("$.name").value("  Padded Tea  ")).andReturn().getResponse().getContentAsString();var fields=fieldNames(new ObjectMapper().readTree(response));Assertions.assertEquals(Set.of("id","name","description","price","currency","stockQuantity","createdAt","updatedAt"),fields);}
 @Test void backfilledLegacyProductIsV1Equivalent() throws Exception {var id=UUID.randomUUID();var when=java.sql.Timestamp.from(Instant.parse("2025-01-02T03:04:05Z"));jdbc.update("INSERT INTO products(id,name,description,price,currency,stock_quantity,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)",id,"Legacy Tea","Legacy fixture",new java.math.BigDecimal("12.30"),"NZD",4,when,when);jdbc.execute("CALL catalog_preflight_and_backfill_legacy_products(500)");mvc.perform(get("/api/v1/products/"+id)).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(id.toString())).andExpect(jsonPath("$.name").value("Legacy Tea")).andExpect(jsonPath("$.description").value("Legacy fixture")).andExpect(jsonPath("$.price").value("12.30")).andExpect(jsonPath("$.currency").value("NZD")).andExpect(jsonPath("$.stockQuantity").value(4));}
 @Test void readinessFailsClosedAndCatalogHasNoCrossContextForeignKeys() throws Exception {Assertions.assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM pg_constraint c JOIN pg_class child ON child.oid=c.conrelid JOIN pg_class parent ON parent.oid=c.confrelid WHERE c.contype='f' AND child.relname IN ('product','product_sku','product_attribute','product_attribute_value','product_attribute_assignment','product_sku_attribute_value','category','product_category','product_image') AND parent.relname NOT IN ('product','product_sku','product_attribute','product_attribute_value','category')",Integer.class));jdbc.update("UPDATE catalog_legacy_reconciliation SET status='NOT_READY' WHERE id=1");mvc.perform(get("/actuator/health/readiness")).andExpect(status().isServiceUnavailable());}
 private static Set<String> fieldNames(JsonNode node){var names=new TreeSet<String>();node.fieldNames().forEachRemaining(names::add);return names;}
}
